   234|/* ── Lusion.co 风格动效 ────────────────────────────────────────────── */
   235|
   236|/* 落子弹跳效果 */
   237|@keyframes stone-drop {
   238|  0% { transform: scale(0) translateY(-20px); opacity: 0; }
   239|  50% { transform: scale(1.1) translateY(0); opacity: 1; }
   240|  70% { transform: scale(0.95); }
   241|  100% { transform: scale(1); opacity: 1; }
   242|}
   243|
   244|/* 落子涟漪效果 */
   245|@keyframes stone-ripple {
   246|  0% { transform: scale(0.8); opacity: 0.5; }
   247|  100% { transform: scale(2); opacity: 0; }
   248|}
   249|
   250|/* 卡片入场 - 交错淡入 */
   251|@keyframes card-enter {
   252|  from { opacity: 0; transform: translateY(20px) scale(0.95); }
   253|  to   { opacity: 1; transform: translateY(0) scale(1); }
