   261|
   262|/* 文字打字机效果 */
   263|@keyframes typewriter {
   264|  from { width: 0; }
   265|  to { width: 100%; }
   266|}
   267|
   268|/* 光标闪烁 */
   269|@keyframes blink-cursor {
   270|  0%, 100% { border-color: transparent; }
   271|  50% { border-color: var(--accent-primary); }
   272|}
   273|
   274|/* 按钮点击波纹 */
   275|@keyframes ripple {
   276|  0% { transform: scale(0); opacity: 0.5; }
   277|  100% { transform: scale(4); opacity: 0; }
   278|}
   279|
   280|/* AI 思考点动画优化 */
   281|@keyframes thinking-dot {
