   290|}
   291|
   292|/* 滑入动画 - 从左 */
   293|@keyframes slide-in-left {
   294|  from { opacity: 0; transform: translateX(-30px); }
   295|  to   { opacity: 1; transform: translateX(0); }
   296|}
   297|
   298|/* 滑入动画 - 从右 */
   299|@keyframes slide-in-right {
   300|  from { opacity: 0; transform: translateX(30px); }
   301|  to   { opacity: 1; transform: translateX(0); }
   302|}
   303|
   304|/* 滑入动画 - 从下 */
   305|@keyframes slide-in-up {
