   307|  to   { opacity: 1; transform: translateY(0); }
   308|}
   309|
   310|/* 淡入缩放 */
   311|@keyframes fade-scale-in {
   312|  from { opacity: 0; transform: scale(0.9); }
   313|  to   { opacity: 1; transform: scale(1); }
   314|}
   315|
   316|/* 呼吸灯效果 - 科技感主题 */
   317|@keyframes breathe {
   318|  0%, 100% { box-shadow: 0 0 5px var(--accent-primary), 0 0 10px transparent; }
   319|  50% { box-shadow: 0 0 10px var(--accent-primary), 0 0 20px var(--accent-primary); }
   320|}
   321|
   322|/* 赢线绘制 */
   323|@keyframes draw-line {
   324|  from { stroke-dashoffset: 1000; }
   325|  to { stroke-dashoffset: 0; }
