   328|/* ─── Utilities ───────────────────────────────────────────────────────────── */
   329|
   330|@layer utilities {
   331|  .stone-black {
   332|    background: radial-gradient(circle at 38% 35%, #5a5a5a, #0a0a0a 60%);
   333|    box-shadow: 0 3px 8px rgba(0,0,0,0.5), inset 0 1px 2px rgba(255,255,255,0.1);
